    Fixture f;CommonStore common(f.seed,f.catalog);const auto before=encode_common_state(common.state());auto recorded=record_family_death(common,f.state,f.reader(),"dead");check(recorded.ok&&f.state.deaths.size()==1,"actual death source not recorded once");const auto* death=family_death_for_actor(f.state,"dead");check(death&&death->death_tick==8&&death->recorded_tick==10&&death->cause_fact_id=="military:1","record lost cause or original date");const auto after=encode_common_state(common.state());for(const auto* key:{"actors","wallets","inventories","roles","player_actor_id"})check(compare_boundary(*before.find(key),*after.find(key)).exact(),"recording death changed control, roles or private resources");check(!validate_family_deaths(common,f.state,f.reader(),false).ok,"disabled profile accepted death history");const auto once=encode_common_state(common.state());auto same=record_family_death(common,f.state,f.reader(),"dead");check(same.ok&&same.value==recorded.value&&compare_boundary(once,encode_common_state(common.state())).exact(),"repeated death duplicated source or IDs");
    auto json=encode_family_deaths(f.state);auto decoded=decode_family_deaths(json);check(decoded.ok&&compare_boundary(json,encode_family_deaths(decoded.value)).exact()&&validate_family_deaths(common,decoded.value,f.reader(),true).ok,"JSON cold state changed source");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_family_deaths_checkpoint(writer,decoded.value).ok&&writer.finish().ok,"typed death writer");const auto& input=bytes;CodecVisitor reader(input);FamilyDeathState cold;check(visit_family_deaths_checkpoint(reader,cold).ok&&reader.finish().ok&&compare_boundary(json,encode_family_deaths(cold)).exact(),"typed death roundtrip changed source");
    auto duplicate=json;duplicate.as<BoundaryValue::Dict>()->emplace_back("deaths",*json.find("deaths"));check(!decode_family_deaths(duplicate).ok,"duplicate death root key accepted");duplicate=json;duplicate.find("deaths")->as<BoundaryValue::Dict>()->front().second.as<BoundaryValue::Dict>()->emplace_back("cause_fact_id",BoundaryValue{"military:other"});check(!decode_family_deaths(duplicate).ok,"duplicate death source key accepted");auto broken=f.state;broken.deaths.rows().front().second.cause_fact_id="military:other";check(!validate_family_deaths(common,broken,f.reader(),true).ok,"unknown causal fact accepted");broken=f.state;broken.deaths.rows().front().second.death_tick=9;check(!validate_family_deaths(common,broken,f.reader(),true).ok,"wrong causal date accepted");broken=f.state;broken.deaths.rows().front().second.world_id[0]=8;check(!validate_family_deaths(common,broken,f.reader(),true).ok,"other-world death source accepted");broken=f.state;broken.deaths.rows().front().second.field_order={"unknown"};CodecVisitor::Buffer bad;CodecVisitor bad_writer(bad);check(!visit_family_deaths_checkpoint(bad_writer,broken).ok,"bad death field order accepted");
    Fixture alive;CommonStore living(alive.seed,alive.catalog);living.state().actors.find("dead")->alive=true;check(!record_family_death(living,alive.state,alive.reader(),"dead").ok&&alive.state.deaths.empty(),"death recorded for living actor");Fixture missing;CommonStore absent(missing.seed,missing.catalog);FamilyDeathOriginRead no_source=[](const StableId&)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,std::nullopt,{}};};check(!record_family_death(absent,missing.state,no_source,"dead").ok&&missing.state.deaths.empty(),"alive=false invented a death origin");
