    Fixture late;CommonStore failing(late.seed,late.catalog);const auto original=encode_common_state(failing.state()),original_deaths=encode_family_deaths(late.state);int reads=0;auto source=late.reader();FamilyDeathOriginRead failure=[&](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{if(++reads==3)return {false,{},common_failure("InjectedDeathSourceUnavailable").error};return source(actor);};auto refused=record_family_death(failing,late.state,failure,"dead");check(!refused.ok&&refused.error.original.code=="InjectedDeathSourceUnavailable"&&reads==3,"late gate was not reached after factual append");check(compare_boundary(original,encode_common_state(failing.state())).exact()&&compare_boundary(original_deaths,encode_family_deaths(late.state)).exact(),"late death source error left partial Common or family life state");Fixture batch;CommonStore batch_common(batch.seed,batch.catalog);const auto batch_before=encode_common_state(batch_common.state());bool first_present=false;auto batch_source=batch.reader();FamilyDeathOriginRead second_error=[&](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{if(actor=="living"){first_present=batch_common.state().facts.find("family_death:2")!=nullptr;return {false,{},common_failure("InjectedSecondDeathSourceFailure").error};}return batch_source(actor);};auto batch_failed=record_family_deaths(batch_common,batch.state,second_error,{"dead","living"});check(!batch_failed.ok&&first_present&&batch.state.deaths.empty()&&compare_boundary(batch_before,encode_common_state(batch_common.state())).exact(),"second death failure left first event in batch");check(!record_family_deaths(batch_common,batch.state,batch.reader(),{"dead","dead"}).ok&&compare_boundary(batch_before,encode_common_state(batch_common.state())).exact(),"duplicate batch actor allocated any fact");auto batch_ok=record_family_deaths(batch_common,batch.state,batch.reader(),{"dead"});check(batch_ok.ok&&batch_ok.value.size()==1&&batch.state.deaths.size()==1,"single real death batch failed");const auto view_before=encode_common_state(common.state());auto living_page=query_family_death_page(common,f.state,f.reader());check(living_page.ok&&*living_page.value.find("status")->as<StableId>()=="living"&&living_page.value.find("death")->as<BoundaryValue::Dict>()->empty(),"living observer leaked another actor death");common.state().metadata.player_actor_id="dead";const auto dead_before=encode_common_state(common.state());auto dead_page=query_family_death_page(common,f.state,f.reader());check(dead_page.ok&&*dead_page.value.find("status")->as<StableId>()=="awaiting_legacy_review"&&*dead_page.value.find("control_confirmation_required")->as<bool>()&&! *dead_page.value.find("assets_transferred")->as<bool>()&&compare_boundary(dead_before,encode_common_state(common.state())).exact(),"death view granted control/assets or changed world");common.state().metadata.player_actor_id="living";check(compare_boundary(view_before,encode_common_state(common.state())).exact(),"death view changed a non-player field");Fixture stage;CommonStore stage_common(stage.seed,stage.catalog);stage_common.state().actors.find("dead")->action_id="unfinished:personal_action";const auto stage_before=encode_common_state(stage_common.state());auto stage_result=record_verified_family_deaths(stage_common,stage.state,stage.reader());check(stage_result.ok&&stage_result.value.size()==1&&stage_common.state().actors.find("dead")->action_id=="unfinished:personal_action"&&compare_boundary(*stage_before.find("wallets"),*encode_common_state(stage_common.state()).find("wallets")).exact(),"stable death recording required dead actor to be free or cleared assets");const auto stage_saved=encode_common_state(stage_common.state());auto stage_again=record_verified_family_deaths(stage_common,stage.state,stage.reader());check(stage_again.ok&&stage_again.value.empty()&&compare_boundary(stage_saved,encode_common_state(stage_common.state())).exact(),"stable phase repeated original death");Fixture initial;CommonStore initial_common(initial.seed,initial.catalog);auto initial_result=record_verified_family_deaths(initial_common,initial.state,no_source);check(initial_result.ok&&initial_result.value.empty()&&initial.state.deaths.empty(),"initial dead flag invented a death source");auto policy=boundary::obj({{"profile",BoundaryValue{StableId{"verified_military_deaths_v1"}}},{"player_death",BoundaryValue{StableId{"await_explicit_continuation"}}}});auto decoded_policy=decode_family_death_policy(policy);check(decoded_policy.ok&&decoded_policy.value.enabled,"explicit authored death policy refused");auto bad_policy=policy;bad_policy.as<BoundaryValue::Dict>()->emplace_back("player_death",BoundaryValue{StableId{"automatic_heir"}});check(!decode_family_death_policy(bad_policy).ok,"duplicate death policy key accepted");*policy.find("player_death")=BoundaryValue{StableId{"automatic_heir"}};check(!decode_family_death_policy(policy).ok,"automatic death continuation silently enabled");check(validate_family_death_coverage(common,f.state,f.reader(),true).ok,"complete death coverage rejected");Fixture erased;CommonStore erased_common(erased.seed,erased.catalog);check(!validate_family_death_coverage(erased_common,erased.state,erased.reader(),true).ok,"deleting both death payload and Common head hid actual casualty");check(validate_family_death_coverage(erased_common,erased.state,no_source,true).ok,"unknown initial dead actor required invented proof");// 本人死亡命令门不依赖UI、命令种类或是否已有原因；其他NPC与旧模式保持原规则。
    Fixture controls;CommonStore control(controls.seed,controls.catalog);const auto control_before=encode_common_state(control.state());check(guard_family_death_player_command(control,{true},"living").ok,"living current player blocked");check(guard_family_death_player_command(control,{true},"dead").ok,"NPC death became player-control block");control.state().metadata.player_actor_id="dead";auto stopped=guard_family_death_player_command(control,{true},"dead");check(!stopped.ok&&stopped.error.original.code=="PlayerDeathContinuationRequired","dead current player still allowed command");check(guard_family_death_player_command(control,{false},"dead").ok,"disabled old profile changed command gate");control.state().metadata.player_actor_id="living";check(compare_boundary(control_before,encode_common_state(control.state())).exact(),"control guard wrote state or source");
    // 原共同导出经真实decode_common_seed回读新头，不用二进制visitor替代JSON入口。
    auto header_state=common.state();for(auto& row:header_state.actors.rows())row.second.appearance=std::make_shared<const AppearanceProfile>();header_state.metadata.ruleset_id="hanmo.native.local_society/1";auto header_json=encode_common_state(header_state);header_json.as<BoundaryValue::Dict>()->emplace_back("results",BoundaryValue{BoundaryValue::Dict{}});auto* header=header_json.find("facts")->find(recorded.value);header->as<BoundaryValue::Dict>()->emplace_back("domain",BoundaryValue{StableId{"family_life"}});auto json_common=decode_common_seed(header_json,*f.catalog,nullptr,CommonSeedValidation::defer_until_bundle);if(!json_common.ok)std::cerr<<"COMMON_JSON "<<json_common.error.original.code<<" "<<json_common.error.original.path<<"\n";check(json_common.ok&&json_common.value.facts.find(recorded.value)->domain=="family_life","new exact declared death header cannot cold decode");auto wrong_header=header_json;*wrong_header.find("facts")->find(recorded.value)->find("kind")=BoundaryValue{StableId{"family_other"}};auto wrong_common=decode_common_seed(wrong_header,*f.catalog,nullptr,CommonSeedValidation::defer_until_bundle);check(!wrong_common.ok&&wrong_common.error.original.code=="InvalidFactDomain","unrelated family kind entered family_life");wrong_header=header_json;*wrong_header.find("facts")->find(recorded.value)->find("domain")=BoundaryValue{StableId{"local_economy"}};wrong_common=decode_common_seed(wrong_header,*f.catalog,nullptr,CommonSeedValidation::defer_until_bundle);check(!wrong_common.ok&&wrong_common.error.original.code=="InvalidFactDomain","death header accepted wrong declared domain");
